import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('Nutrify exige identidade e preserva operação sem prescrever dose',()=>{const p={id:'C8VXX9MfKS8ULwDiDWXn',titulo:'Collagen Renew Sabor Laranja - Nutrify 300g',preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.equal(x.preco,p.preco);assert.equal(x.linkAfiliado,p.linkAfiliado);assert.deepEqual(correctProductData(x),x);assert.match(x.comentario,/Não prescrevemos dose/);assert.doesNotMatch(x.pros,/glúten|anos|absorção|resultado/i);assert.equal(correctProductData({...p,titulo:'Outro produto',comentario:'manter'}).comentario,'manter');});
